// Парсинг данных обновления задачи из Битрикс24
const input = $input.first().json.body || $input.first().json;
const result = {};

for (const [key, value] of Object.entries(input)) {
  const matches = key.match(/^([^\[]+)(?:\[([^\]]+)\])?(?:\[([^\]]+)\])?$/);

  if (matches) {
    const [, first, second, third] = matches;

    if (third) {
      result[first] = result[first] || {};
      result[first][second] = result[first][second] || {};
      result[first][second][third] = value;
    } else if (second) {
      result[first] = result[first] || {};
      result[first][second] = value;
    } else {
      result[first] = value;
    }
  }
}

return { json: result };

// Парсинг данных из Битрикс24
// Битрикс отправляет данные в формате: data[FIELDS_AFTER][ID] = 123
// Преобразуем в вложенный объект: {data: {FIELDS_AFTER: {ID: 123}}}

// Данные приходят в body вебхука
const input = $input.first().json.body || $input.first().json;
const result = {};

for (const [key, value] of Object.entries(input)) {
  // Разбираем ключи вида: data[FIELDS_AFTER][ID]
  const matches = key.match(/^([^\[]+)(?:\[([^\]]+)\])?(?:\[([^\]]+)\])?$/);

  if (matches) {
    const [, first, second, third] = matches;

    if (third) {
      // Три уровня: data[FIELDS_AFTER][ID]
      result[first] = result[first] || {};
      result[first][second] = result[first][second] || {};
      result[first][second][third] = value;
    } else if (second) {
      // Два уровня: auth[domain]
      result[first] = result[first] || {};
      result[first][second] = value;
    } else {
      // Один уровень: event
      result[first] = value;
    }
  }
}

return { json: result };

